# Fixed version
def flood_fill_from_2(grid, row, col, visited):
    rows = len(grid)
    cols = len(grid[0])
    result = []

    queue = [(row, col)]
    visited.add((row, col))

    while queue:
        r, c = queue.pop(0)
        result.append((r, c))

        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] != 8 and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append((nr, nc))

    return result

def flood_to_all_2s(grid):
    rows = len(grid)
    cols = len(grid[0])

    result = [row[:] for row in grid]
    visited = set()

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 2:
                visited.clear()
                reachable = flood_fill_from_2(grid, r, c, visited)
                for (rr, cc) in reachable:
                    if result[rr][cc] == 0:
                        result[rr][cc] = 2

    return result

